// Normalise the form payload and reject obvious junk before spending AI tokens
const body = $('Contact form webhook').first().json.body || {};
const clean = (v, max) => String(v ?? '').trim().slice(0, max);
const need = clean(body.need ?? body.service ?? body.whatDoYouNeed, 120);
const budget = clean(body.budget, 60);
const note = clean(body.message, 3000);
// Fold the form's dropdowns into one message so Claude and the database see everything
const message = [need && `Needs: ${need}`, budget && `Budget: ${budget}`, note].filter(Boolean).join('\n');
const lead = {
  name: clean(body.name, 120),
  email: clean(body.email, 200).toLowerCase(),
  phone: clean(body.phone, 40),
  company: clean(body.company ?? body.business, 160),
  message,
  source: clean(body.source || 'website', 60),
};
const emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(lead.email);
if (!lead.name || !emailOk || !message) {
  throw new Error('Invalid lead: name, valid email and what they need are required');
}
return [{ json: lead }];

// Pull Claude's JSON out of the response (handles every output shape) and fall back safely if parsing fails
const lead = $('Validate input').first().json;
const j = $json;
let text = '';
if (typeof j.merged_response === 'string') text = j.merged_response;
else if (Array.isArray(j.content)) text = j.content.filter(b => b.type === 'text').map(b => b.text).join('');
else if (typeof j.text === 'string') text = j.text;
else text = JSON.stringify(j);
let ai;
try {
  ai = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (e) {
  ai = { score: 'warm', service: 'unknown', budget_signal: 'unknown',
         summary: 'AI parsing failed - review manually', reply_draft: '' };
}
const score = ['hot', 'warm', 'cold'].includes(ai.score) ? ai.score : 'warm';
return [{ json: { ...lead, ...ai, score } }];
